#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;
namespace FileCompass {
 internal sealed partial class QuickPreviewPane {internal bool PictureFitsForTests{get{return picture.TransformToAncestor(this).Transform(new Point(0,picture.ActualHeight)).Y<=ActualHeight+1;}}internal string[] SelectionPathsForTests{get{return selectionFiles.Select(x=>x.FullPath).ToArray();}}internal double PictureHeightForTests{get{return picture.ActualHeight;}}internal string LoadedPathForTests{get{return current;}}internal void ArrowForTests(Key key){selectionStrip.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(this),0,key){RoutedEvent=Keyboard.PreviewKeyDownEvent});}}
 public partial class FilePanel {internal string DetailGeometryForTests{get{return "panel="+ActualHeight+" gridMax="+detailGrid.MaxHeight+" grid="+detailGrid.ActualHeight+" row="+detailRow.ActualHeight+" rowMin="+detailRow.MinHeight+" body="+detailBody.ActualHeight+" pane="+fileDetail.ActualHeight;}}internal QuickPreviewPane DetailPaneForTests{get{return fileDetail;}}}
 internal static class PreviewSelectionTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow main=null;string motif=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);checks.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs-CZ");FluentTheme.Ensure();AppearanceTheme.Apply("Light");string files=Directory.CreateDirectory(Path.Combine(root,"soubory")).FullName;for(int i=0;i<10;i++){var bitmap=BitmapSource.Create(48,32,96,96,PixelFormats.Bgra32,null,Enumerable.Range(0,48*32).SelectMany(x=>new byte[]{(byte)(i*20),120,220,255}).ToArray(),48*4);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(bitmap));using(var output=File.Create(Path.Combine(files,"obrázek-"+i+".png")))encoder.Save(output);}string document=Path.Combine(files,"z-dokument.txt");File.WriteAllText(document,"Dokument pro společný náhled.");
   foreach(string style in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(style);main=new MainWindow(files,new ProgramSettings{AutoRefresh=false}){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};main.Show();NavigationTests.WaitPanels(main);var panel=FluentUiTests.Children<FilePanel>(main).First();panel.MarkAll(true);var originalCursor=panel.List.SelectedItem;var preview=main.PreviewInOtherPanel(panel);NavigationTests.Wait(preview.LoadingTask);main.UpdateLayout();check(preview.SelectionCount==11,style+": ten images and a text document appear in the selection strip");int marks=panel.List.Items.Cast<Entry>().Count(x=>x.IsMarked);
    preview.SelectPreviewIndex(4);NavigationTests.Wait(preview.LoadingTask);check(preview.LoadedPathForTests==preview.SelectionPathsForTests[4],style+": clicking a strip choice changes the enlarged preview");check(Object.ReferenceEquals(originalCursor,panel.List.SelectedItem)&&panel.List.Items.Cast<Entry>().Count(x=>x.IsMarked)==marks,style+": preview navigation leaves panel cursor and marks unchanged");
    preview.ArrowForTests(Key.Right);NavigationTests.Wait(preview.LoadingTask);check(preview.SelectedPreviewIndex==5&&preview.LoadedPathForTests==preview.SelectionPathsForTests[5],style+": Right arrow selects the next preview");preview.ArrowForTests(Key.Left);NavigationTests.Wait(preview.LoadingTask);check(preview.SelectedPreviewIndex==4,style+": Left arrow selects previous preview");
    int docIndex=Array.IndexOf(preview.SelectionPathsForTests,document);preview.SelectPreviewIndex(docIndex);NavigationTests.Wait(preview.LoadingTask);check(preview.LoadedPathForTests==document,style+": mixed text document uses the same selection strip");preview.SelectPreviewIndex(1);NavigationTests.Wait(preview.LoadingTask);main.UpdateLayout();NextStageTests.Draw(main,Path.Combine(root,style+"-multi-preview.png"));
    panel.ToggleMark(panel.List.Items.Cast<Entry>().First(x=>x.FullPath==document));check(preview.SelectionCount==10,style+": changing marks updates the strip without cursor movement");
    main.PreviewInOtherPanel(panel);main.SetPanelLayout("Single");panel.SetDetailExpanded(true);NavigationTests.Wait(panel.DetailLoadingTask);var detail=panel.DetailPaneForTests;check(detail!=null&&detail.SelectionCount==10,style+": bottom detail supports the same multi-selection");detail.SelectPreviewIndex(7);NavigationTests.Wait(detail.LoadingTask);check(detail.LoadedPathForTests==detail.SelectionPathsForTests[7],style+": bottom preview switches selected image");main.UpdateLayout();File.WriteAllText(Path.Combine(root,style+"-detail-geometry.txt"),panel.DetailGeometryForTests);check(detail.PictureHeightForTests>=60&&detail.PictureFitsForTests,style+": bottom filmstrip leaves visible space for enlarged image");main.UpdateLayout();NextStageTests.Draw(main,Path.Combine(root,style+"-bottom-preview.png"));main.Close();main=null;
   }File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(main!=null)main.Close();AppearanceTheme.SetMotif(motif);}}
 }
}
#endif
